import{_ as t,o as h,c,a3 as a}from"./chunks/framework.DX_KL3e0.js";const o="/help/screenshots/to-chuc/tong-quan.png",p=JSON.parse('{"title":"Quản lý Tổ chức","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/to-chuc.md","filePath":"chuc-nang/to-chuc.md","lastUpdated":1781638739000}'),i={name:"chuc-nang/to-chuc.md"};function g(r,n,l,s,e,u){return h(),c("div",null,[...n[0]||(n[0]=[a('<h1 id="quan-ly-to-chuc" tabindex="-1">Quản lý Tổ chức <a class="header-anchor" href="#quan-ly-to-chuc" aria-label="Permalink to &quot;Quản lý Tổ chức&quot;">​</a></h1><p>Module <strong>Tổ Chức</strong> quản lý toàn bộ cơ cấu doanh nghiệp: công ty, bộ phận/phòng ban, chức vụ, vị trí công việc và nhãn (tags) phân loại — làm nền tảng cho hồ sơ nhân sự và phân quyền.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/organization</code> (menu <strong>Tổ Chức</strong> ở nhóm <em>Điều Hướng</em>).</li><li><strong>Ai dùng được:</strong> Super Admin, Admin (mặc định không có quyền Xóa), Quản lý (chỉ xem).</li><li><strong>Phân hệ:</strong> Cơ Cấu Tổ Chức · Chức Vụ · Vị Trí Công Việc · Tags.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+o+'" alt="Trang Tổ chức"></p><p>Trang tổng quan gồm:</p><ol><li><strong>Lưới thống kê</strong> — số liệu nhanh: số Công Ty, Chức Vụ, Bộ Phận, Vị Trí Công Việc, tổng Nhân Viên và Nhân Viên Hoạt Động.</li><li><strong>Lưới phân hệ</strong> — 4 thẻ dẫn vào từng phần quản lý chi tiết.</li></ol><h2 id="cac-phan-he" tabindex="-1">Các phân hệ <a class="header-anchor" href="#cac-phan-he" aria-label="Permalink to &quot;Các phân hệ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phân hệ</th><th>Đường dẫn</th><th>Dùng để</th></tr></thead><tbody><tr><td><strong>Cơ Cấu Tổ Chức</strong></td><td><code>/organization/companies-organization</code></td><td>Quản lý công ty, bộ phận, phòng ban và cơ cấu tổ chức chung.</td></tr><tr><td><strong>Chức Vụ</strong></td><td><code>/organization/positions</code></td><td>Quản lý chức vụ (vị trí) và gán cho nhân viên của từng công ty.</td></tr><tr><td><strong>Vị Trí Công Việc</strong></td><td><code>/organization/job-titles</code></td><td>Tạo danh sách vị trí công việc theo công ty để cấu hình tổ chức.</td></tr><tr><td><strong>Tags</strong></td><td><code>/organization/tags</code></td><td>Tạo tags hệ thống để phân loại, đánh dấu người dùng theo tiêu chí.</td></tr></tbody></table><h2 id="thao-tac-chinh" tabindex="-1">Thao tác chính <a class="header-anchor" href="#thao-tac-chinh" aria-label="Permalink to &quot;Thao tác chính&quot;">​</a></h2><h3 id="xem-so-lieu-tong-quan" tabindex="-1">Xem số liệu tổng quan <a class="header-anchor" href="#xem-so-lieu-tong-quan" aria-label="Permalink to &quot;Xem số liệu tổng quan&quot;">​</a></h3><ol><li>Mở <strong>Tổ Chức</strong> từ menu.</li><li>Đọc lưới thống kê ở đầu trang để nắm nhanh quy mô tổ chức.</li></ol><h3 id="quan-ly-co-cau-to-chuc-cong-ty-bo-phan-phong-ban" tabindex="-1">Quản lý Cơ cấu tổ chức (công ty, bộ phận, phòng ban) <a class="header-anchor" href="#quan-ly-co-cau-to-chuc-cong-ty-bo-phan-phong-ban" aria-label="Permalink to &quot;Quản lý Cơ cấu tổ chức (công ty, bộ phận, phòng ban)&quot;">​</a></h3><ol><li>Nhấn thẻ <strong>Cơ Cấu Tổ Chức</strong>.</li><li>Tạo/chỉnh sửa <strong>công ty</strong>, sau đó thêm <strong>bộ phận</strong> và <strong>phòng ban</strong> trực thuộc.</li><li>(Tùy chọn) Tải <strong>logo công ty</strong> trong cửa sổ thêm/sửa công ty.</li><li>Lưu thay đổi.</li></ol><div class="tip custom-block"><p class="custom-block-title">Logo công ty</p><p>Trong cửa sổ thêm/sửa công ty có mục <strong>Logo công ty</strong>: tải ảnh PNG/JPG/SVG (≤ 2MB), hệ thống tự giữ tỉ lệ. Nên dùng <strong>logo nền trong suốt</strong> (PNG/SVG) — ảnh sẽ hiển thị trong sơ đồ tổ chức và ở thẻ nhân sự của công ty đó. Vì giao diện nền tối, ưu tiên logo màu sáng để dễ nhìn.</p></div><h3 id="quan-ly-chuc-vu" tabindex="-1">Quản lý Chức vụ <a class="header-anchor" href="#quan-ly-chuc-vu" aria-label="Permalink to &quot;Quản lý Chức vụ&quot;">​</a></h3><ol><li>Nhấn thẻ <strong>Chức Vụ</strong>.</li><li>Thêm các chức vụ cho từng công ty (ví dụ Trưởng phòng, Chuyên viên…).</li><li>Chức vụ sẽ dùng để gán cho nhân viên trong hồ sơ nhân sự.</li></ol><h3 id="quan-ly-vi-tri-cong-viec" tabindex="-1">Quản lý Vị trí công việc <a class="header-anchor" href="#quan-ly-vi-tri-cong-viec" aria-label="Permalink to &quot;Quản lý Vị trí công việc&quot;">​</a></h3><ol><li>Nhấn thẻ <strong>Vị Trí Công Việc</strong>.</li><li>Tạo danh sách vị trí công việc theo từng công ty.</li></ol><h3 id="quan-ly-tags-nhan-to-chuc" tabindex="-1">Quản lý Tags (nhãn tổ chức) <a class="header-anchor" href="#quan-ly-tags-nhan-to-chuc" aria-label="Permalink to &quot;Quản lý Tags (nhãn tổ chức)&quot;">​</a></h3><ol><li>Nhấn thẻ <strong>Tags</strong>.</li><li>Tạo nhãn để phân loại, đánh dấu người dùng theo các tiêu chí riêng.</li></ol><div class="tip custom-block"><p class="custom-block-title">Cần quyền tương ứng</p><p>Các nút Thêm/Sửa/Xóa chỉ hiện nếu tài khoản của bạn có quyền trên module Tổ Chức. Vai trò <strong>Quản lý</strong> chỉ xem; <strong>Admin</strong> mặc định không có quyền Xóa. Xem <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a>.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Khác nhau giữa &quot;Chức Vụ&quot; và &quot;Vị Trí Công Việc&quot;?</strong><strong>Chức Vụ</strong> là cấp bậc/vị trí được gán cho nhân viên (ví dụ Trưởng phòng). <strong>Vị Trí Công Việc</strong> là danh mục vị trí theo công ty dùng để cấu hình cơ cấu. Cả hai đều thiết lập theo từng công ty.</p><p><strong>Tags ở đây có giống tags nhân viên không?</strong> Tags tổ chức là nhãn hệ thống dùng phân loại người dùng, tách biệt với các nhãn khác. Hãy đặt tên nhãn rõ ràng để dễ quản lý.</p><p><strong>Vì sao tôi chỉ xem được mà không sửa?</strong> Vai trò Quản lý chỉ có quyền xem module Tổ Chức. Cần chỉnh sửa, hãy đề nghị Admin/Super Admin.</p><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a> · <a href="/help/chuc-nang/dashboard.html">Dashboard</a></p>',28)])])}const m=t(i,[["render",g]]);export{p as __pageData,m as default};
